import re, sys, unicodedata
src, out = sys.argv[1], sys.argv[2]
def norm(s):
    s = unicodedata.normalize('NFC', s)
    for a in '“”″': s = s.replace(a, '"')
    for a in '‘’': s = s.replace(a, "'")
    s = re.sub(r'- \d+ -', '', s)
    return re.sub(r'\s+', ' ', s).strip()
blocks = {}
cur = None
for line in open(src, encoding='utf-8'):
    m = re.match(r'### (조:\S.*)$', line.rstrip())
    if m: cur = m.group(1).strip(); blocks[cur] = ''; continue
    if cur: blocks[cur] += line
nb = {k: norm(v) for k, v in blocks.items()}
txt = open(out, encoding='utf-8').read()
provs = re.findall(r'^### (조:.*)$', txt, re.M)
print('provisions', len(provs), 'input', len(blocks), 'missing', set(blocks) - set(provs))
concepts, rels, norms_ = set(), 0, 0
newc = set()
bad = 0
for blk in re.split(r'^### ', txt, flags=re.M)[1:]:
    pid = blk.split('\n', 1)[0].strip()
    body = blk.split('\n', 1)[1]
    in_rel = in_norm = False
    for line in body.split('\n'):
        if line.startswith('개념:'):
            for m in re.finditer(r'(\S+:\S+) \((기존|신규)\)', line):
                concepts.add(m.group(1))
                if m.group(2) == '신규': newc.add(m.group(1))
        if line.startswith('관계:'): in_rel, in_norm = True, False
        elif line.startswith('규범:'): in_rel, in_norm = False, True
        elif not line.startswith('      '): in_rel = in_norm = False
        if in_rel and ' -' in line and '-> ' in line: rels += 1
        if in_norm and re.search(r'규범:재도전/|규범:공통/', line): norms_ += 1
        if in_rel or in_norm:
            if ' | ' in line and in_norm:
                for cell in line.split(' | '):
                    if cell.strip().startswith('문장') and '"' in cell: print('QUOTE IN 문장', pid)
            for q in re.findall(r'"([^"]*)"', line):
                tgt = nb.get(pid, '')
                m2 = re.search(r'근거 (조:\S+) "', line)
                if m2: tgt = nb.get(m2.group(1), '')
                if norm(q) not in tgt:
                    bad += 1; print('BAD', pid, '|', q)
print('concepts', len(concepts), 'new', len(newc), sorted(newc))
print('relations', rels, 'norms', norms_, 'bad excerpts', bad)
